export function getProductImgHash(p) {
  if (!p) return '';
  if (p.imgHash) return p.imgHash;
  const path = p.img || (Array.isArray(p.gallery) && p.gallery[0]) || '';
  if (!path) return '';
  const clean = path.replace(/^\//, '');
  return IMAGE_HASH_MAP[clean] || IMAGE_HASH_MAP['/' + clean] || path;
}

